<template><section class="space-y-5"><h1 class="text-2xl font-bold text-white">供应商消息</h1><div class="grid gap-5 lg:grid-cols-3"><div class="space-y-3"><button v-for="item in threads" :key="item.id" class="pc-card w-full text-left" @click="open(item)"><p class="font-semibold text-white">{{ item.subject }}</p><p class="text-xs text-slate-400">{{ item.status }}</p></button></div><div class="pc-card lg:col-span-2"><div v-for="item in messages" :key="item.id" class="mb-3 border-b border-white/10 pb-3"><p class="text-sm text-slate-200">{{ item.body }}</p></div><form v-if="active" class="flex gap-3" @submit.prevent="send"><input v-model="body" class="input-field" required placeholder="Message"/><button class="btn-primary">Send</button></form></div></div><p v-if="error" class="text-red-300">{{ error }}</p></section></template>
<script setup lang="ts">definePageMeta({layout:'procurement',middleware:['auth'],alias:['/supplier/inbox']});const api=useCommerce();const threads=ref<any[]>([]);const messages=ref<any[]>([]);const active=ref<any>();const body=ref('');const error=ref('');async function open(item:any){active.value=item;messages.value=(await api.listMessages(item.id)).items}async function send(){await api.postMessage(active.value.id,body.value);body.value='';await open(active.value)}onMounted(async()=>{try{threads.value=(await api.listThreads()).items;const orderId=String(useRoute().query.order_id||'');const selected=threads.value.find(x=>x.commerce_order_id===orderId)||threads.value[0];if(selected)await open(selected)}catch(e:any){error.value=e?.data?.detail||e?.message}})</script>
